"use client"

import { useAsyncOptions, type AsyncOptionsStatus } from "@ui-sdk/react/async-options"
import type { SearchFilter } from "@ui-sdk/react/command"
import { matchRanges, matchSegments, type MatchRange } from "@ui-sdk/react/text-match"
import { useMemo, useRef, useState, type ReactNode } from "react"

import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandItemText,
  CommandList,
  CommandRows,
  CommandStatus,
  type CommandData,
  type CommandDataItem,
} from "@/components/ui/command"
import { CommandDialog, CommandDialogContent } from "@/components/ui/command-dialog"
import { useDocumentWorkspace } from "@/components/ui/document-workspace-context"
import type { PageSource } from "@/lib/page-source"

type DocumentQuickOpenItem = {
  value: string
  label: string
  /** A folder or path, shown after the label. */
  description?: string
  /**
   * A passage of the note, like the one a search matched: a muted second line under the label, cut at two lines,
   * with the query's words marked. Plain text; agents and screen readers read it with the label.
   */
  snippet?: string
  keywords?: readonly string[]
  /** Items with the same group are listed under it. */
  group?: string
}

type DocumentQuickOpenLabels = {
  title: string
  placeholder?: string
  /** Shown when nothing matches: text, or a function of the query. */
  empty: ReactNode | ((query: string) => ReactNode)
  /** Shown while the first results load, and read out while any load. */
  loading: string
  /** Shown, and read out, when a search fails. */
  error: string
  /** Read out once results are in. */
  count: (count: number) => string
}

const documentQuickOpenLabels: Omit<DocumentQuickOpenLabels, "title"> = {
  empty: "No matches",
  loading: "Searching…",
  error: "Couldn't search",
  count: (count) => `${String(count)} ${count === 1 ? "result" : "results"}`,
}

type DocumentQuickOpenBaseProps = {
  onOpen: (value: string) => void
  labels?: Partial<DocumentQuickOpenLabels>
}

type DocumentQuickOpenItemsProps = DocumentQuickOpenBaseProps & {
  items: readonly DocumentQuickOpenItem[]
  /**
   * How typing narrows `items`: `"fuzzy"` (default), `"contains"`, `"startsWith"` or a function. `false` keeps every
   * item in its order, for results your own search already matched, like a note found by its body.
   */
  filter?: SearchFilter<string>
  /** Hears the query as it changes, to run your own search and pass its results as `items`. */
  onQueryChange?: (query: string) => void
  /** Your search's state: `"loading"` dims the list and is read out, `"error"` says the search failed. */
  status?: AsyncOptionsStatus
  source?: never
}

type DocumentQuickOpenSourceProps<T> = DocumentQuickOpenBaseProps & {
  /**
   * Searches on the server as you type, with the query as `filter.q` (no `q` while it's empty): requests wait for
   * typing to pause and a newer one aborts the last, the next page loads at the end of the list, and the server's
   * order and matches are kept, whatever the titles say.
   */
  source: PageSource<T, { q?: string }>
  /** What a result shows and the value `onOpen` gets. */
  getItem: (item: T) => DocumentQuickOpenItem
  pageSize?: number
  /** How long typing must pause before a search, in ms. Default 200. */
  debounce?: number
  items?: never
}

type DocumentQuickOpenProps<T = unknown> = DocumentQuickOpenItemsProps | DocumentQuickOpenSourceProps<T>

type QuickOpenListProps = {
  items: readonly DocumentQuickOpenItem[]
  labels: DocumentQuickOpenLabels
  onOpen: (value: string) => void
  filter?: SearchFilter<string>
  onQueryChange?: (query: string) => void
  status?: AsyncOptionsStatus
  onLoadMore?: () => void
}

type QuickOpenCommand = CommandDataItem & { description?: string; snippet?: string }

/** Every place each word of the query appears in `text`, matched as the command filter matches (case, accents). */
function queryRanges(text: string, query: string) {
  const ranges: MatchRange[] = []
  for (const word of new Set(query.trim().split(/\s+/u).filter(Boolean))) {
    let from = 0
    while (from < text.length) {
      const [range] = matchRanges(text.slice(from), word, "contains")
      if (!range || range.end <= range.start) break
      ranges.push({ start: from + range.start, end: from + range.end })
      from += range.end
    }
  }
  ranges.sort((a, b) => a.start - b.start)
  const merged: MatchRange[] = []
  for (const range of ranges) {
    const last = merged.at(-1)
    if (last && range.start <= last.end) last.end = Math.max(last.end, range.end)
    else merged.push({ ...range })
  }
  return merged
}

function QuickOpenSnippet({ text, query }: { text: string; query: string }) {
  const segments = useMemo(() => matchSegments(text, queryRanges(text, query)), [text, query])
  return (
    <span data-slot="quick-open-snippet" className="line-clamp-2 text-caption text-muted-foreground">
      <span className="sr-only">, </span>
      {segments.map((segment, at) =>
        segment.match ? (
          // oxlint-disable-next-line react/no-array-index-key -- the snippet's pieces have no identity beyond their place
          <mark key={at} className="bg-transparent font-semibold text-current">
            {segment.text}
          </mark>
        ) : (
          segment.text
        ),
      )}
    </span>
  )
}

// A row with a snippet is the label's line and up to two of `text-caption`, measured once it renders.
const snippetRows =
  "[&_[data-slot=command-item]:has(>[data-slot=quick-open-snippet])]:h-auto [&_[data-slot=command-item]:has(>[data-slot=quick-open-snippet])]:flex-col [&_[data-slot=command-item]:has(>[data-slot=quick-open-snippet])]:items-stretch [&_[data-slot=command-item]:has(>[data-slot=quick-open-snippet])]:gap-0 [&_[data-slot=command-item]:has(>[data-slot=quick-open-snippet])]:py-inset-item"
const snippetRowSize = (item: QuickOpenCommand) => (item.snippet ? 52 : undefined)

// Items with a group are listed under it, groups in the order their first item comes.
function quickOpenData(items: readonly DocumentQuickOpenItem[]): CommandData {
  const groups = new Map<string, QuickOpenCommand[]>()
  for (const { group = "", keywords, ...item } of items) {
    const command: QuickOpenCommand = { ...item, ...(keywords && { keywords: [...keywords] }) }
    groups.set(group, [...(groups.get(group) ?? []), command])
  }
  return [...groups].flatMap(([group, entries]): CommandData =>
    group ? [{ type: "group", label: group, items: entries }] : entries,
  )
}

// The items go to Command as data and render through CommandRows: past 50, only the rows in view mount, so a vault
// of notes opens on the next frame, while typing, the arrows and agents still reach every one.
function QuickOpenList({ items, labels, onOpen, status, onQueryChange, filter, onLoadMore }: QuickOpenListProps) {
  const workspace = useDocumentWorkspace()
  const data = useMemo(() => quickOpenData(items), [items])
  // CommandList's state has no query; the snippets mark what was typed.
  const [query, setQuery] = useState("")
  const empty = (text: string) => (typeof labels.empty === "function" ? labels.empty(text) : labels.empty)
  return (
    <Command
      items={data}
      status={status}
      filter={filter}
      onLoadMore={onLoadMore}
      onQueryChange={(next) => {
        setQuery(next)
        onQueryChange?.(next)
      }}
      onAction={(value) => {
        workspace.quickOpen.close()
        onOpen(value)
      }}
    >
      <CommandInput aria-label={labels.title} placeholder={labels.placeholder} />
      {/* Only a search that reports its state gets a status region; a local filter keeps the list's announcement. */}
      {status !== undefined && (
        <CommandStatus className="sr-only">
          {(state) =>
            state.status === "error" ? labels.error : state.loading ? labels.loading : labels.count(state.count)
          }
        </CommandStatus>
      )}
      <CommandEmpty>
        {(state) =>
          status === "error" ? labels.error : state.loading ? labels.loading : state.empty ? empty(state.query) : null
        }
      </CommandEmpty>
      <CommandList className={snippetRows}>
        {(state) => (
          <CommandRows<QuickOpenCommand> items={state.items} estimateItemSize={snippetRowSize}>
            {(item) => {
              const title = (
                <>
                  <CommandItemText className="truncate" />
                  {item.description && (
                    <span className="ms-auto shrink-0 truncate text-caption text-muted-foreground">
                      <span className="sr-only">, </span>
                      {item.description}
                    </span>
                  )}
                </>
              )
              if (!item.snippet) return title
              return (
                <>
                  <span className="flex min-w-0 items-center gap-inline">{title}</span>
                  <QuickOpenSnippet text={item.snippet} query={query} />
                </>
              )
            }}
          </CommandRows>
        )}
      </CommandList>
    </Command>
  )
}

type SourceListProps<T> = Omit<DocumentQuickOpenSourceProps<T>, "labels"> & { labels: DocumentQuickOpenLabels }

/** Mounted while the dialog is open, so a closed quick open never searches. */
function SourceList<T>({ source, getItem, pageSize = 20, debounce = 200, labels, onOpen }: SourceListProps<T>) {
  const cursors = useRef(new Map<number, string | null>())
  const results = useAsyncOptions<DocumentQuickOpenItem>(
    async (query, { signal, page }) => {
      if (page === 0) cursors.current = new Map([[0, null]])
      const position =
        source.capabilities.position === "cursor"
          ? { cursor: cursors.current.get(page) ?? null, direction: "forward" as const }
          : { page: page + 1 }
      const q = query.trim()
      const result = await source.fetchPage(
        { filter: q === "" ? {} : { q }, sort: [], size: pageSize, position },
        { signal },
      )
      if (result.nextCursor) cursors.current.set(page + 1, result.nextCursor)
      return { items: result.items.map(getItem), hasMore: result.hasMore ?? (result.nextCursor ?? null) !== null }
    },
    { debounce, immediate: true },
  )
  return (
    <QuickOpenList
      items={results.items}
      labels={labels}
      onOpen={onOpen}
      filter={false}
      status={results.status}
      onQueryChange={(query) => results.setQuery(query)}
      onLoadMore={results.loadMore}
    />
  )
}

/**
 * Ctrl/Cmd+P in a `DocumentWorkspace`: calls `onOpen` with the chosen value, then focus goes back to the document.
 * `items` are searched in the browser, or listed as they are with `filter={false}`, `onQueryChange` and `status`;
 * a `source` with `getItem` searches the server, debounced, stale responses dropped, more loading at the end.
 */
function DocumentQuickOpen<T>(props: DocumentQuickOpenProps<T>) {
  const workspace = useDocumentWorkspace()
  const labels = { title: workspace.labels.quickOpen, ...documentQuickOpenLabels, ...props.labels }
  return (
    <CommandDialog
      controller={workspace.quickOpen}
      onOpenChangeComplete={(open) => open || workspace.refocusDocument()}
    >
      <CommandDialogContent title={labels.title} finalFocus={workspace.documentFocusTarget}>
        {props.source ? (
          <SourceList {...props} labels={labels} />
        ) : (
          <QuickOpenList
            items={props.items}
            labels={labels}
            onOpen={props.onOpen}
            filter={props.filter}
            onQueryChange={props.onQueryChange}
            status={props.status}
          />
        )}
      </CommandDialogContent>
    </CommandDialog>
  )
}

export { DocumentQuickOpen, documentQuickOpenLabels }
export type {
  DocumentQuickOpenItem,
  DocumentQuickOpenItemsProps,
  DocumentQuickOpenLabels,
  DocumentQuickOpenProps,
  DocumentQuickOpenSourceProps,
}

"use client"

import type { ReactNode, RefObject } from "react"
import { BookOpenIcon, PanelLeftIcon, PanelRightIcon, PencilIcon, SearchIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { CommandDialogTrigger } from "@/components/ui/command-dialog"
import type { DocumentSaveState, DocumentWorkspaceMode } from "@/components/ui/document-workspace-context"
import { SegmentedControl, SegmentedControlIndicator, SegmentedControlItem } from "@/components/ui/segmented-control"
import { StatusDot } from "@/components/ui/status-pill"
import type { DocumentWorkspaceState } from "@/components/ui/use-document-workspace-state"
import type { Tone } from "@/lib/tone"

const SAVE_TONES: Record<DocumentSaveState, Tone> = {
  saved: "success",
  saving: "info",
  unsaved: "warning",
  error: "destructive",
}

const toggleClassName = "shrink-0 text-muted-foreground aria-expanded:text-foreground"

type WorkspaceHeaderProps = {
  state: DocumentWorkspaceState
  tabs: ReactNode
  hasExplorer: boolean
  hasAside: boolean
  hasQuickOpen: boolean
  quickOpenShortcut: string | false
}

/** The explorer toggle, the tabs, the mode switch, quick open and the aside toggle. */
function WorkspaceHeader({
  state,
  tabs,
  hasExplorer,
  hasAside,
  hasQuickOpen,
  quickOpenShortcut,
}: WorkspaceHeaderProps) {
  const { labels, ids, context, explorer, aside } = state
  return (
    <div
      data-slot="document-workspace-header"
      className="flex min-w-0 flex-wrap items-center gap-inline border-b px-inset-item py-inline"
    >
      {hasExplorer && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={labels.explorerToggle}
          aria-expanded={explorer.shown}
          aria-controls={ids.explorer}
          onClick={() => explorer.setOpen(!explorer.shown)}
          className={toggleClassName}
        >
          <PanelLeftIcon className="rtl:-scale-x-100" />
        </Button>
      )}
      {/* A narrow column gives the tabs a row of their own instead of squeezing them beside the controls. */}
      <div
        data-slot="document-workspace-tabs"
        className="min-w-0 flex-1 @max-xl/center:order-last @max-xl/center:basis-full"
      >
        {tabs}
      </div>
      <SegmentedControl<DocumentWorkspaceMode>
        aria-label={labels.mode}
        value={context.mode}
        onValueChange={(next) => next && context.setMode(next)}
        className="ms-auto shrink-0"
      >
        <SegmentedControlIndicator />
        <SegmentedControlItem value="edit" className="@max-xl:px-inline">
          <PencilIcon />
          <span className="@max-xl:sr-only">{labels.edit}</span>
        </SegmentedControlItem>
        <SegmentedControlItem value="read" className="@max-xl:px-inline">
          <BookOpenIcon />
          <span className="@max-xl:sr-only">{labels.read}</span>
        </SegmentedControlItem>
      </SegmentedControl>
      {hasQuickOpen && (
        <CommandDialogTrigger
          controller={context.quickOpen}
          shortcut={quickOpenShortcut || undefined}
          variant="ghost"
          size="icon"
          aria-label={labels.quickOpen}
          className={toggleClassName}
        >
          <SearchIcon />
        </CommandDialogTrigger>
      )}
      {hasAside && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={labels.asideToggle}
          aria-expanded={aside.shown}
          aria-controls={ids.aside}
          onClick={() => aside.setOpen(!aside.shown)}
          className={toggleClassName}
        >
          <PanelRightIcon className="rtl:-scale-x-100" />
        </Button>
      )}
    </div>
  )
}

type WorkspaceCenterProps = Omit<WorkspaceHeaderProps, "tabs"> & {
  tabs?: ReactNode
  breadcrumb?: ReactNode
  toolbar?: ReactNode
  statusBar?: ReactNode
  saveState?: DocumentSaveState
  documentAs: "region" | "main"
  documentRef: RefObject<HTMLElement | null>
  children: ReactNode
}

/** The header, the breadcrumb bar, the document region and the status bar, in a column. */
function WorkspaceCenter({
  state,
  tabs,
  breadcrumb,
  toolbar,
  statusBar,
  saveState,
  documentAs,
  documentRef,
  children,
  ...header
}: WorkspaceCenterProps) {
  const { labels, context } = state
  const Document = documentAs === "main" ? "main" : "section"
  return (
    <div data-slot="document-workspace-center" className="@container/center flex size-full min-h-0 min-w-0 flex-col">
      <WorkspaceHeader state={state} tabs={tabs} {...header} />
      {(breadcrumb !== undefined || toolbar !== undefined) && (
        <div
          data-slot="document-workspace-bar"
          className="flex min-w-0 flex-wrap items-center gap-items border-b px-inset-item py-inline"
        >
          <div className="min-w-0 flex-1">{breadcrumb}</div>
          {toolbar !== undefined && <div className="flex shrink-0 items-center gap-inline">{toolbar}</div>}
        </div>
      )}
      <Document
        ref={documentRef}
        tabIndex={-1}
        aria-label={labels.document}
        data-slot="document-workspace-document"
        data-mode={context.mode}
        // oxlint-disable-next-line eskais/scroll-area -- the page-level document, which hosts the editor (see markdown-editor.tsx)
        className="flex min-h-0 flex-1 flex-col overflow-auto outline-none data-[mode=read]:px-inset-surface data-[mode=read]:py-group"
      >
        {children}
      </Document>
      <div
        data-slot="document-workspace-status"
        className="flex min-w-0 items-center gap-items border-t px-inset-item py-inline text-caption text-muted-foreground"
      >
        <div className="flex min-w-0 flex-1 items-center gap-items">{statusBar}</div>
        <output data-state={saveState} className="inline-flex shrink-0 items-center gap-inline">
          {saveState && (
            <>
              <StatusDot tone={SAVE_TONES[saveState]} pulse={saveState === "saving"} label="" aria-hidden="true" />
              {labels[saveState]}
            </>
          )}
        </output>
      </div>
    </div>
  )
}

export { WorkspaceCenter }
export type { WorkspaceCenterProps }

"use client"

import type { CommandDialogController } from "@/components/ui/command-dialog"
import { createContext, use, type RefObject } from "react"

type DocumentWorkspaceMode = "edit" | "read"
type DocumentSaveState = "saved" | "saving" | "unsaved" | "error"

/** A heading of the open document, as `extractHeadings` (from `markdown-view`) returns it. */
type DocumentHeading = {
  level: number
  text: string
  line: number
  textFrom: number
  /** The anchor `MarkdownView` puts on the rendered heading (`data-slug`); read mode finds the heading by it. */
  slug?: string
}

/** What the workspace needs from an editor: `MarkdownEditorHandle` (from `markdown-editor`) has it. */
type DocumentEditor = {
  focus: () => void
  scrollToLine: (line: number) => void
  setSelection: (anchor: number, head?: number) => void
  getScrollLine: () => number
}

type DocumentWorkspaceLabels = {
  /** The explorer's navigation landmark and drawer title. */
  explorer: string
  /** The button that shows or hides the explorer. */
  explorerToggle: string
  /** The aside's complementary landmark and drawer title. */
  aside: string
  asideToggle: string
  /** The document region. */
  document: string
  /** The mode switch and its two choices. */
  mode: string
  edit: string
  read: string
  quickOpen: string
  resizeExplorer: string
  resizeAside: string
  saved: string
  saving: string
  unsaved: string
  error: string
}

const documentWorkspaceLabels: DocumentWorkspaceLabels = {
  explorer: "Files",
  explorerToggle: "Files",
  aside: "Details",
  asideToggle: "Details",
  document: "Document",
  mode: "Mode",
  edit: "Edit",
  read: "Read",
  quickOpen: "Quick open",
  resizeExplorer: "Resize files",
  resizeAside: "Resize details",
  saved: "Saved",
  saving: "Saving…",
  unsaved: "Unsaved changes",
  error: "Couldn't save",
}

type DocumentWorkspaceContextValue = {
  mode: DocumentWorkspaceMode
  /** Switches the mode, keeping the reading position by heading. */
  setMode: (mode: DocumentWorkspaceMode) => void
  narrow: boolean
  headings: readonly DocumentHeading[]
  editorRef: RefObject<DocumentEditor | null> | undefined
  /** The document region, which scrolls in read mode. */
  documentRef: RefObject<HTMLElement | null>
  /** Where focus goes back to: the editor's text in edit mode, the document region in read mode. */
  documentFocusTarget: () => HTMLElement | null
  /** Focuses the document once it is there: an editor that remounts for another note builds its view later. */
  focusDocument: () => void
  /** After a popup closed: focuses the document if focus was left nowhere in particular. */
  refocusDocument: () => void
  /**
   * Read mode: scrolls a heading to the top and moves focus to it. Pass a heading from `extractHeadings`, found by
   * its `slug` (a filtered list still finds the right one), or by its text without one; a number is the index among
   * the rendered headings.
   */
  revealHeading: (heading: DocumentHeading | number) => void
  quickOpen: CommandDialogController
  /** Shows or hides the explorer: its column when wide, its drawer when narrow. */
  setExplorerOpen: (open: boolean) => void
  /**
   * Closes the explorer drawer in the narrow layout, as a link in it does; the wide layout's column stays. Call it
   * when a button in your tree opens a document, or pass `documentId` to the workspace instead.
   */
  closeExplorer: () => void
  setAsideOpen: (open: boolean) => void
  labels: DocumentWorkspaceLabels
}

const DocumentWorkspaceContext = createContext<DocumentWorkspaceContextValue | null>(null)

/** The enclosing `DocumentWorkspace`: its mode, headings, editor and focus helpers. */
function useDocumentWorkspace() {
  const context = use(DocumentWorkspaceContext)
  if (!context) throw new Error("useDocumentWorkspace needs a DocumentWorkspace around it.")
  return context
}

/** The rendered headings of a read view in `root`, leaving out any inside an embed. */
function readHeadings(root: HTMLElement | null) {
  if (!root) return []
  return [...root.querySelectorAll<HTMLElement>("h1, h2, h3, h4, h5, h6")].filter(
    (heading) => !heading.closest("[data-slot=markdown-embed], [data-slot=markdown-properties]"),
  )
}

/** The rendered heading for `heading`: by its slug, else the first with its text; a number is an index. */
function findHeading(root: HTMLElement | null, heading: DocumentHeading | number) {
  const rendered = readHeadings(root)
  if (typeof heading === "number") return rendered[heading]
  if (heading.slug !== undefined) {
    const bySlug = rendered.find((element) => element.dataset.slug === heading.slug)
    if (bySlug) return bySlug
  }
  return rendered.find((element) => element.textContent.replace(/\s+/g, " ").trim() === heading.text)
}

function textBoxIn(root: HTMLElement | null) {
  return root?.querySelector<HTMLElement>("[contenteditable=true], [role=textbox], textarea") ?? null
}

export { DocumentWorkspaceContext, documentWorkspaceLabels, findHeading, readHeadings, textBoxIn, useDocumentWorkspace }
export type {
  DocumentEditor,
  DocumentHeading,
  DocumentSaveState,
  DocumentWorkspaceContextValue,
  DocumentWorkspaceLabels,
  DocumentWorkspaceMode,
}

"use client"

import type { ComponentProps, MouseEvent, ReactNode } from "react"

import { Drawer, DrawerBackdrop, DrawerContent, DrawerTitle } from "@/components/ui/drawer"
import { Resizable, ResizableHandle, ResizablePanel } from "@/components/ui/resizable"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import type { DocumentWorkspaceState } from "@/components/ui/use-document-workspace-state"

type WorkspaceDrawerProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  side: "start" | "end"
  title: string
  finalFocus: ComponentProps<typeof DrawerContent>["finalFocus"]
  onClosed: () => void
  children: ReactNode
}

/** The explorer or the aside in the narrow layout: a 20rem drawer from its side, named by its landmark. */
function WorkspaceDrawer({ open, onOpenChange, side, title, finalFocus, onClosed, children }: WorkspaceDrawerProps) {
  return (
    <Drawer open={open} onOpenChange={onOpenChange} onOpenChangeComplete={(next) => next || onClosed()} side={side}>
      <DrawerBackdrop />
      <DrawerContent finalFocus={finalFocus} className="gap-0 p-0 data-[side=left]:max-w-80 data-[side=right]:max-w-80">
        <DrawerTitle className="sr-only">{title}</DrawerTitle>
        {children}
      </DrawerContent>
    </Drawer>
  )
}

type PanelsProps = { state: DocumentWorkspaceState; explorer?: ReactNode; aside?: ReactNode }

/** A column's content, scrolling inside the panel that names it. */
function PanelScroll({ children }: { children: ReactNode }) {
  return (
    <ScrollArea className="size-full">
      <ScrollAreaViewport>{children}</ScrollAreaViewport>
      <ScrollAreaScrollbar data-agent-hidden="" />
      <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
    </ScrollArea>
  )
}

/** The wide layout: the explorer, the center and the aside as resizable columns that collapse to nothing. */
function WorkspaceColumns({ state, explorer, aside, children }: PanelsProps & { children: ReactNode }) {
  const { ids, labels, stored, controller } = state
  return (
    <Resizable controller={controller} onLayoutCommit={state.remember} className="min-h-0 flex-1">
      {explorer !== undefined && (
        <>
          <ResizablePanel
            id={ids.explorer}
            collapsible
            collapsedSize={0}
            minSize="180px"
            maxSize="45%"
            defaultSize={state.explorer.open ? (stored.explorerSize ?? "256px") : 0}
            render={<nav aria-label={labels.explorer} />}
            data-slot="document-workspace-explorer"
            className="overflow-hidden bg-muted/(--glass-opacity)"
          >
            <PanelScroll>{explorer}</PanelScroll>
          </ResizablePanel>
          <ResizableHandle aria-label={labels.resizeExplorer} />
        </>
      )}
      <ResizablePanel id={ids.center} minSize="320px" className="overflow-hidden">
        {children}
      </ResizablePanel>
      {aside !== undefined && (
        <>
          <ResizableHandle aria-label={labels.resizeAside} />
          <ResizablePanel
            id={ids.aside}
            collapsible
            collapsedSize={0}
            minSize="220px"
            maxSize="45%"
            defaultSize={state.aside.open ? (stored.asideSize ?? "288px") : 0}
            render={<aside aria-label={labels.aside} />}
            data-slot="document-workspace-aside"
            className="overflow-hidden"
          >
            <PanelScroll>{aside}</PanelScroll>
          </ResizablePanel>
        </>
      )}
    </Resizable>
  )
}

/** The narrow layout: the explorer and the aside as drawers from their sides. */
function WorkspaceDrawers({ state, explorer, aside }: PanelsProps) {
  const { ids, labels, context } = state
  const onClosed = () => context.refocusDocument()

  // A file chosen in the drawer is navigation: the drawer closes and focus goes to the document.
  const closeOnLink = (event: MouseEvent<HTMLElement>) => {
    if (event.target instanceof Element && event.target.closest("a[href]")) state.explorer.setOpen(false)
  }

  return (
    <>
      {explorer !== undefined && (
        <WorkspaceDrawer
          open={state.explorer.drawerOpen}
          onOpenChange={state.explorer.setOpen}
          side="start"
          title={labels.explorer}
          finalFocus={context.documentFocusTarget}
          onClosed={onClosed}
        >
          <ScrollArea className="flex min-h-0 flex-1 flex-col">
            <ScrollAreaViewport
              id={ids.explorer}
              aria-label={labels.explorer}
              // Hears the clicks of the links inside, which Enter fires too.
              onClick={closeOnLink}
              className="h-auto min-h-0 flex-1"
              render={(part) => <nav {...part} data-slot="document-workspace-explorer" />}
            >
              {explorer}
            </ScrollAreaViewport>
            <ScrollAreaScrollbar data-agent-hidden="" />
            <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
          </ScrollArea>
        </WorkspaceDrawer>
      )}
      {aside !== undefined && (
        <WorkspaceDrawer
          open={state.aside.drawerOpen}
          onOpenChange={state.aside.setOpen}
          side="end"
          title={labels.aside}
          finalFocus={context.documentFocusTarget}
          onClosed={onClosed}
        >
          <ScrollArea className="flex min-h-0 flex-1 flex-col">
            <ScrollAreaViewport
              id={ids.aside}
              aria-label={labels.aside}
              className="h-auto min-h-0 flex-1"
              render={(part) => <aside {...part} data-slot="document-workspace-aside" />}
            >
              {aside}
            </ScrollAreaViewport>
            <ScrollAreaScrollbar data-agent-hidden="" />
            <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
          </ScrollArea>
        </WorkspaceDrawer>
      )}
    </>
  )
}

